void ov80_0222A140(const FrontierPokemon *frontierMon, Pokemon *mon, s32 setLevel);

void ov80_0222A480(FieldBattleDTO *battleDTO, FrontierTrainer *trainer, int unused, int battlerId, enum HeapID heapID);

void ov80_02236A34(FieldBattleDTO *battleDTO, FrontierOpponent *opponent, int partySize, int battlerId, enum HeapID heapID);

void ov80_02236A34(FieldBattleDTO *battleDTO, FrontierOpponent *opponent, int partySize, int battlerId, enum HeapID heapID) {
    ov80_0222A480(battleDTO, &opponent->trainer, partySize, battlerId, heapID);
    Pokemon *mon = AllocMonZeroed(heapID);

    for (int i = 0; i < partySize; i++) {
        ov80_0222A140(&opponent->pokemon[i], mon, 120);
        Party_AddMon(battleDTO->parties[battlerId], mon);
    }

    Heap_Free(mon);
}
